  async terminate(id: string): Promise<Employee | null> {
    const existing = await this.repo.findById(id);
    if (!existing) {
      return null;
    }
    const updated = await this.repo.update(id, {
      employmentStatus: EmploymentStatus.TERMINATED,
      terminationDate: new Date(),
    });
    if (!updated) {
      return null;
    }

    const now = new Date();
    const auditRecord: AuditRecord = {
      id: crypto.randomUUID(),
      entityType: 'Employee',
      entityId: updated.id,
      action: 'TERMINATE',
      oldValues: this.employeeToRecord(existing),
      newValues: this.employeeToRecord(updated),
      performedBy: 'system',
      performedAt: now,
      ipAddress: undefined,
      userAgent: undefined,
      createdAt: now,
    };
    await this.auditRepo.create(auditRecord);

    return updated;
  }

  private employeeToRecord(employee: Employee): Record<string, unknown> {
    return {
      id: employee.id,
      employeeNumber: employee.employeeNumber,
      firstName: employee.firstName,
      lastName: employee.lastName,
      email: employee.email,
      managerId: employee.managerId,
      department: employee.department,
      hireDate: employee.hireDate,
      terminationDate: employee.terminationDate,
      employmentStatus: employee.employmentStatus,
      createdAt: employee.createdAt,
      updatedAt: employee.updatedAt,
      deletedAt: employee.deletedAt,
    };
  }
}

